/** DECKFLOW library → documented rekordbox XML interchange (not a USB writer).
 * Native device files are generated by the pinned MIT-licensed baken helper.
 */
const MAX_TRACKS = 10000;
const fail = message => { throw new Error(message); };
const xml = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[char]));
const text = (value, label, max = 256) => {
  if (typeof value !== 'string' || value.length > max || /[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(value)) fail(`${label}の文字列を確認してください。`);
  return value;
};
const position = (value, duration, label) => {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0 || value >= duration) fail(`${label}が曲の範囲外です。`);
  return value;
};

export function validateUsbLibrary(input) {
  let data = input;
  if (typeof input === 'string') {
    if (input.length > 64 * 1024 * 1024) fail('ライブラリJSONが64 MiBを超えています。');
    try { data = JSON.parse(input); } catch { fail('ライブラリJSONを読み込めません。'); }
  }
  if (!data || data.format !== 'deckflow.library' || data.version !== 1 || !Array.isArray(data.tracks) ||
      data.tracks.length < 1 || data.tracks.length > MAX_TRACKS) fail('DECKFLOWのバージョン1ライブラリJSONを指定してください（1〜10,000曲）。');
  const ids = new Set();
  const tracks = data.tracks.map((track, index) => {
    if (!track || !['string','number'].includes(typeof track.id)) fail(`${index + 1}曲目のIDがありません。`);
    const id = text(String(track.id), '曲ID');
    if (!id || ids.has(id)) fail('曲IDが空、または重複しています。');
    ids.add(id);
    const filename = text(track.filename, '音源ファイル名', 255);
    if (!filename || filename === '.' || filename === '..' || /[\\/]/.test(filename)) fail('音源ファイル名にフォルダや相対パスは指定できません。');
    const duration = track.duration;
    if (typeof duration !== 'number' || !Number.isFinite(duration) || duration <= 0 || duration > 65535) fail(`${filename}: 曲の長さを確認してください。`);
    const bpm = track.bpm;
    if (typeof bpm !== 'number' || !Number.isFinite(bpm) || bpm < 20 || bpm > 600) fail(`${filename}: USB書き出し前にBPMを解析、または入力してください（20〜600）。`);
    const hotcues = Array.from({length: 4}, (_, i) => track.hotcues?.[i] == null ? null : position(track.hotcues[i], duration, `${filename} HOT CUE ${i + 1}`));
    const date = track.addedAt == null ? null : new Date(track.addedAt);
    return {id, filename, title: text(track.title || filename.replace(/\.[^.]+$/, ''), '曲名'),
      artist: text(track.artist || '', 'アーティスト'), bpm, duration,
      beatOffset: position(track.beatOffset ?? 0, duration, `${filename}の拍位置`),
      cue: position(track.cue ?? 0, duration, `${filename}のCUE`), hotcues,
      addedAt: date && Number.isFinite(date.getTime()) ? date.toISOString() : null,
      addedDate: date && Number.isFinite(date.getTime()) ? date.toISOString().slice(0,10) : ''};
  });
  if (data.playlists !== undefined && !Array.isArray(data.playlists)) fail('プレイリストの形式を確認してください。');
  if ((data.playlists?.length || 0) > 1000) fail('プレイリストは1,000個までです。');
  const playlistIds = new Set();
  const playlists = (data.playlists || []).map((playlist, index) => {
    if (!playlist || !Array.isArray(playlist.trackIds)) fail('プレイリストの曲順を確認してください。');
    const id = text(String(playlist.id ?? index), 'プレイリストID');
    if (playlistIds.has(id)) fail('プレイリストIDが重複しています。');
    playlistIds.add(id);
    const name = text(playlist.name, 'プレイリスト名', 200);
    if (!name.trim()) fail('プレイリスト名を入力してください。');
    const trackIds = playlist.trackIds.map(value => String(value));
    if (trackIds.some(value => !ids.has(value))) fail(`${name}: ライブラリにない曲が含まれています。`);
    return {id, name, trackIds};
  });
  return {format:'deckflow.library', version:1, targetDevice:'CDJ-3000', tracks, playlists};
}

/** Generate file://localhost URLs without allowing remote hosts or shell syntax. */
export function encodeRekordboxLocation(path) {
  if (typeof path !== 'string' || !path.startsWith('/') || path.includes('\0')) fail('音源の絶対パスが必要です。');
  let encoded = '';
  for (const byte of new TextEncoder().encode(path)) {
    const char = String.fromCharCode(byte);
    encoded += /[A-Za-z0-9/.:_~-]/.test(char) ? char : `%${byte.toString(16).toUpperCase().padStart(2,'0')}`;
  }
  return `file://localhost${encoded}`;
}

export function buildRekordboxXml(input, locations) {
  const library = validateUsbLibrary(input);
  const lookup = locations instanceof Map ? locations : new Map(Object.entries(locations || {}));
  const ids = new Map(library.tracks.map((track, i) => [track.id, i + 1]));
  let allName = 'DECKFLOW ALL';
  while (library.playlists.some(item => item.name === allName)) allName += ' ·';
  const playlists = [{name: allName, trackIds: library.tracks.map(track => track.id)}, ...library.playlists];
  const rows = library.tracks.map(track => {
    const path = lookup.get(track.id);
    if (!path) fail(`${track.filename}: 音源の保存場所がありません。`);
    const location = encodeRekordboxLocation(path);
    const attrs = {TrackID: ids.get(track.id), Name:track.title, Artist:track.artist,
      Kind: `${track.filename.split('.').at(-1).toUpperCase()} File`, TotalTime:Math.ceil(track.duration),
      AverageBpm:track.bpm.toFixed(2), Location:location, DateAdded:track.addedDate, Rating:0};
    const attributes = Object.entries(attrs).map(([key,value]) => `${key}="${xml(value)}"`).join(' ');
    const cueRows = [`      <POSITION_MARK Name="DECKFLOW CUE" Type="0" Start="${track.cue.toFixed(6)}" Num="-1"/>`];
    track.hotcues.forEach((cue, index) => {
      if (cue !== null) cueRows.push(`      <POSITION_MARK Name="HOT CUE ${index + 1}" Type="0" Start="${cue.toFixed(6)}" Num="${index}"/>`);
    });
    return `    <TRACK ${attributes}>\n      <TEMPO Inizio="${track.beatOffset.toFixed(6)}" Bpm="${track.bpm.toFixed(6)}" Metro="4/4" Battito="1"/>\n${cueRows.join('\n')}\n    </TRACK>`;
  });
  const lists = playlists.map(playlist => `      <NODE Type="1" Name="${xml(playlist.name)}" KeyType="0" Entries="${playlist.trackIds.length}">\n${playlist.trackIds.map(id => `        <TRACK Key="${ids.get(id)}"/>`).join('\n')}\n      </NODE>`);
  const output = `<?xml version="1.0" encoding="UTF-8"?>\n<DJ_PLAYLISTS Version="1.0.0">\n  <PRODUCT Name="DECKFLOW" Version="0.1.0" Company="DECKFLOW"/>\n  <COLLECTION Entries="${rows.length}">\n${rows.join('\n')}\n  </COLLECTION>\n  <PLAYLISTS>\n    <NODE Type="0" Name="ROOT" Count="${lists.length}">\n${lists.join('\n')}\n    </NODE>\n  </PLAYLISTS>\n</DJ_PLAYLISTS>\n`;
  return {xml: output, library, numericIds: Object.fromEntries(ids), playlists};
}
